				{
					final ExportStatsToIJAction action = new ExportStatsToIJAction( selectionModel );
					action.execute( trackmate );
				}
				finally
				{
					button.setEnabled( true );
				}
			}
		}.start();
	}

	@Plugin( type = TrackMateActionFactory.class )
